using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
namespace Overclock {
 sealed class OpenRgbStudio:IStudioProvider {
  readonly StudioQueue queue=new StudioQueue();readonly int port;TcpClient client;NetworkStream stream;DateTime retry;int failures;bool disposed;
  public OpenRgbStudio(int port){if(port<1||port>65535)throw new ArgumentOutOfRangeException("port");this.port=port;}
  public static bool HasRange(uint value,uint min,uint max){return min!=max&&value>=Math.Min(min,max)&&value<=Math.Max(min,max);}
  public static int Normalize(uint value,uint min,uint max){if(!HasRange(value,min,max))throw new InvalidDataException("Invalid RGB range");return (int)Math.Round(((long)value-min)*100.0/((long)max-min));}
  public static uint Raw(int percent,uint min,uint max){if(percent<0||percent>100||min==max)throw new InvalidDataException("Invalid RGB value");return (uint)Math.Round(min+((long)max-min)*percent/100.0);}
  static byte[] Bytes(Action<BinaryWriter> write){using(var m=new MemoryStream()){using(var w=new BinaryWriter(m,Encoding.UTF8,true))write(w);return m.ToArray();}}
  static void Text(BinaryWriter w,string s){byte[] b=Encoding.UTF8.GetBytes(s+"\0");if(b.Length>4096)throw new InvalidDataException("RGB string too long");w.Write((ushort)b.Length);w.Write(b);}
  static string Text(BinaryReader r){int n=r.ReadUInt16();if(n<1||n>4096||n>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Invalid RGB string length");byte[] b=r.ReadBytes(n);if(b[n-1]!=0)throw new InvalidDataException("Unterminated RGB string");return new UTF8Encoding(false,true).GetString(b,0,n-1);}
  static uint[] Colors(BinaryReader r){int n=r.ReadUInt16();if(n>16384||n*4>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Invalid RGB colour count");var c=new uint[n];for(int i=0;i<n;i++)c[i]=r.ReadUInt32();return c;}
  static StudioMode Mode(BinaryReader r){return new StudioMode{Name=Text(r),Value=r.ReadInt32(),Flags=r.ReadUInt32(),SpeedMin=r.ReadUInt32(),SpeedMax=r.ReadUInt32(),BrightnessMin=r.ReadUInt32(),BrightnessMax=r.ReadUInt32(),ColorsMin=r.ReadUInt32(),ColorsMax=r.ReadUInt32(),Speed=r.ReadUInt32(),Brightness=r.ReadUInt32(),Direction=r.ReadUInt32(),ColorMode=r.ReadUInt32(),Colors=Colors(r)};}
  static void Mode(BinaryWriter w,StudioMode m){Text(w,m.Name);w.Write(m.Value);w.Write(m.Flags);w.Write(m.SpeedMin);w.Write(m.SpeedMax);w.Write(m.BrightnessMin);w.Write(m.BrightnessMax);w.Write(m.ColorsMin);w.Write(m.ColorsMax);w.Write(m.Speed);w.Write(m.Brightness);w.Write(m.Direction);w.Write(m.ColorMode);w.Write((ushort)m.Colors.Length);foreach(uint c in m.Colors)w.Write(c);}
  public static StudioDevice Parse(byte[] data,uint index){if(data.Length>2*1024*1024)throw new InvalidDataException("RGB packet too large");using(var r=new BinaryReader(new MemoryStream(data))){if(r.ReadUInt32()!=data.Length)throw new InvalidDataException("RGB packet length mismatch");r.ReadInt32();var d=new StudioDevice{Index=index,Name=Text(r)};string vendor=Text(r),description=Text(r),version=Text(r),serial=Text(r),location=Text(r);using(var sha=SHA256.Create())d.Id=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(vendor+"\n"+d.Name+"\n"+serial+"\n"+location))).Replace("-","");d.Ambiguous=string.IsNullOrEmpty(serial)&&string.IsNullOrEmpty(location);int count=r.ReadUInt16();if(count>256)throw new InvalidDataException("Too many RGB modes");d.ActiveMode=r.ReadInt32();for(int i=0;i<count;i++){var mode=Mode(r);if((mode.Flags&64)!=0&&(mode.ColorsMin>mode.ColorsMax||mode.ColorsMax>16384))throw new InvalidDataException("Invalid RGB mode colour count");d.Modes.Add(mode);}if(d.ActiveMode<0||d.ActiveMode>=count&&count!=0)throw new InvalidDataException("Invalid active RGB mode");count=r.ReadUInt16();if(count>256)throw new InvalidDataException("Too many RGB zones");for(int i=0;i<count;i++){string name=Text(r);r.ReadUInt32();r.ReadUInt32();r.ReadUInt32();uint leds=r.ReadUInt32();if(leds>16384)throw new InvalidDataException("Too many LEDs");int matrix=r.ReadUInt16();if(matrix>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Invalid RGB matrix length");r.ReadBytes(matrix);d.Zones.Add(new StudioZone{Index=i,Id=name+"/"+leds,Name=name,LedCount=(int)leds});}count=r.ReadUInt16();if(count>16384)throw new InvalidDataException("Too many RGB LEDs");for(int i=0;i<count;i++){Text(r);r.ReadUInt32();}d.Colors=Colors(r);if(r.BaseStream.Position!=data.Length)throw new InvalidDataException("Unexpected RGB trailing data");d.ObservedUtc=DateTime.UtcNow;d.StateSource="OpenRGB SDK cache; physical readback unavailable";d.Status=d.Ambiguous?"Identity unavailable / read-only":"Connected";d.Detail=vendor+" / "+d.Zones.Count+" zones / "+count+" LEDs";return d;}}
  void Send(uint device,uint id,byte[] data){if(data.Length>2*1024*1024)throw new InvalidDataException("RGB packet too large");var header=Bytes(w=>{w.Write(Encoding.ASCII.GetBytes("ORGB"));w.Write(device);w.Write(id);w.Write((uint)data.Length);});stream.Write(header,0,header.Length);stream.Write(data,0,data.Length);}
  byte[] Read(int length){var b=new byte[length];int p=0;while(p<length){int n=stream.Read(b,p,length-p);if(n==0)throw new IOException("OpenRGB disconnected");p+=n;}return b;}
  byte[] Receive(uint device,uint id){var watch=Stopwatch.StartNew();for(int i=0;i<32;i++){if(watch.ElapsedMilliseconds>4000)throw new TimeoutException("OpenRGB response timeout");byte[] h=Read(16);if(Encoding.ASCII.GetString(h,0,4)!="ORGB")throw new InvalidDataException("Invalid OpenRGB signature");uint dev=BitConverter.ToUInt32(h,4),kind=BitConverter.ToUInt32(h,8),n=BitConverter.ToUInt32(h,12);if(n>2*1024*1024)throw new InvalidDataException("OpenRGB packet exceeds bound");byte[] data=Read((int)n);if(kind==100)throw new IOException("RGB device list changed. Refresh before applying.");if(dev==device&&kind==id)return data;}throw new IOException("Unexpected OpenRGB responses");}
  void Connect(){if(stream!=null)return;if(DateTime.UtcNow<retry)throw new IOException("OpenRGB reconnect backoff; wait a few seconds and reconnect");client=new TcpClient(AddressFamily.InterNetwork);try{var connected=client.ConnectAsync(IPAddress.Loopback,port);if(!connected.Wait(2500))throw new TimeoutException();connected.GetAwaiter().GetResult();}catch(Exception error){throw new IOException("No OpenRGB SDK server is reachable at 127.0.0.1:"+port+". Start OpenRGB 1.1, open SDK Server, set host 127.0.0.1 and this port, then Start Server. BenchMark X connects through OpenRGB; it cannot detect RGB hardware without that provider.",error);}stream=client.GetStream();stream.ReadTimeout=3500;stream.WriteTimeout=3500;Send(0,40,BitConverter.GetBytes((uint)3));byte[] version=Receive(0,40);if(version.Length!=4||BitConverter.ToUInt32(version,0)<3)throw new InvalidDataException("OpenRGB SDK protocol 3 or later is required");Send(0,50,Encoding.UTF8.GetBytes("BenchMark X Studio\0"));}
  List<StudioDevice> Inventory(){Send(0,0,new byte[0]);byte[] data=Receive(0,0);if(data.Length!=4)throw new InvalidDataException("Invalid OpenRGB inventory");uint count=BitConverter.ToUInt32(data,0);if(count>128)throw new InvalidDataException("Too many RGB devices");var list=new List<StudioDevice>();for(uint i=0;i<count;i++){Send(i,1,BitConverter.GetBytes((uint)3));list.Add(Parse(Receive(i,1),i));}foreach(var g in list.GroupBy(d=>d.Id).Where(g=>g.Count()>1))foreach(var d in g){d.Ambiguous=true;d.Status="Ambiguous identity / read-only";}return list;}
  public Task<StudioReply> Execute(StudioCommand command,CancellationToken cancel){return queue.Run(token=>Task.Run(()=>{try{if(disposed)throw new ObjectDisposedException("RGB Studio");using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(token)){deadline.CancelAfter(12000);using(deadline.Token.Register(()=>Disconnect())){Connect();token.ThrowIfCancellationRequested();var devices=Inventory();if(command.Action=="discover")return new StudioReply{Devices=devices,Message=devices.Count+" OpenRGB device(s). SDK state is not physical readback."};var d=devices.SingleOrDefault(x=>x.Id==command.Id&&!x.Ambiguous);if(d==null)throw new IOException("RGB device missing or ambiguous. Refresh.");if(command.Action=="read")return new StudioReply{Devices=new List<StudioDevice>{d}};if(command.Action!="apply"&&command.Action!="restore")throw new InvalidDataException("Unknown RGB command");var previous=command.Snapshot;int mi=command.Action=="restore"&&previous!=null?d.Modes.FindIndex(m=>m.Name==previous.Modes[previous.ActiveMode].Name):d.Modes.FindIndex(m=>m.Name==command.Mode);if(mi<0)throw new InvalidOperationException("RGB mode no longer supported");var mode=StudioJson.Clone(d.Modes[mi]);if((mode.Flags&512)!=0)throw new InvalidOperationException("Mode automatically saves to hardware; unsupported in this reversible release");uint[] colors=d.Colors;StudioZone zone=null;if(command.Zone!=null){zone=d.Zones.SingleOrDefault(z=>z.Id==command.Zone);if(zone==null)throw new InvalidOperationException("Zone changed. Refresh.");if((mode.Flags&32)==0)throw new InvalidOperationException("This effect controls the whole device; choose All zones");}
    if(command.Action=="restore"){if(previous==null||previous.Id!=d.Id||previous.Colors.Length!=d.Colors.Length)throw new InvalidDataException("Restore snapshot no longer compatible");mode=StudioJson.Clone(previous.Modes[previous.ActiveMode]);colors=previous.Colors;}else{if(command.Speed.HasValue){if((mode.Flags&1)==0)throw new InvalidOperationException("Speed unsupported");mode.Speed=Raw(command.Speed.Value,mode.SpeedMin,mode.SpeedMax);}if(command.Brightness.HasValue){if((mode.Flags&16)==0)throw new InvalidOperationException("Brightness unsupported");mode.Brightness=Raw(command.Brightness.Value,mode.BrightnessMin,mode.BrightnessMax);}if(command.Hex!=null){if(!System.Text.RegularExpressions.Regex.IsMatch(command.Hex,"^#[a-fA-F0-9]{6}$"))throw new InvalidDataException("Use #RRGGBB");Color c=ColorTranslator.FromHtml(command.Hex);uint packed=(uint)(c.R|c.G<<8|c.B<<16);if((mode.Flags&32)!=0){mode.ColorMode=1;colors=Enumerable.Repeat(packed,zone==null?d.Colors.Length:zone.LedCount).ToArray();}else if((mode.Flags&64)!=0){mode.ColorMode=2;int n=(int)Math.Max(mode.ColorsMin,Math.Min(mode.ColorsMax,(uint)Math.Max(1,mode.Colors.Length)));mode.Colors=Enumerable.Repeat(packed,n).ToArray();}else throw new InvalidOperationException("Colour unsupported by this mode");}}
    token.ThrowIfCancellationRequested();if(stream.DataAvailable)throw new IOException("OpenRGB state changed before apply. Refresh before retrying.");byte[] modeData=Bytes(w=>{w.Write((uint)0);w.Write(mi);Mode(w,mode);});Array.Copy(BitConverter.GetBytes((uint)modeData.Length),modeData,4);Send(d.Index,1101,modeData);if((mode.Flags&32)!=0){byte[] ledData=Bytes(w=>{w.Write((uint)(6+colors.Length*4+(zone==null?0:4)));if(zone!=null)w.Write(zone.Index);w.Write((ushort)colors.Length);foreach(uint color in colors)w.Write(color);});Send(d.Index,zone==null?1050u:1051u,ledData);}failures=0;return new StudioReply{Devices=Inventory(),Message="Commands sent to OpenRGB. SDK cached state only; physical LED readback unavailable."};}}
   }catch{Disconnect();failures=Math.Min(5,failures+1);retry=DateTime.UtcNow.AddSeconds(Math.Pow(2,failures));throw;}},token),cancel);}
  void Disconnect(){var c=client;stream=null;client=null;if(c!=null)c.Close();}
  public void Dispose(){disposed=true;queue.Dispose();Disconnect();}
 }
}
